const A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
const CODE = new Map([...A].map((c, i) => [c, i]))
let syllables = null
let tradMap = null

function ensure() {
  if (syllables) return
  syllables = SYLLABLES.split(',')
  tradMap = new Map()
  // 必须按码位遍历，不能按 UTF-16 单元下标。
  // OpenCC 有少数繁体字会映射到扩展 B 区（U+20000 以上），那些字在 JS 里占两个单元，
  // 用 TRAD[i] / SIMP[i] 对齐会从那一位开始整体错位 —— 表现是「越靠后的字转得越离谱」。
  const trad = [...TRAD]
  const simp = [...SIMP]
  for (let i = 0; i < trad.length; i++) tradMap.set(trad[i], simp[i] ?? trad[i])
}

/** 单个汉字的全拼；不是收录范围内的汉字返回空串 */
export function pinyinOfChar(ch) {
  const cp = ch.codePointAt(0)
  if (cp < PY_BASE || cp > PY_END) return ''
  ensure()
  const at = (cp - PY_BASE) * 2
  const hi = CODE.get(INDEX[at]) ?? 0
  const lo = CODE.get(INDEX[at + 1]) ?? 0
  return syllables[hi * 64 + lo] || ''
}

/** 繁体单字转简体；不是繁体就原样返回 */
export function simplifyChar(ch) {
  ensure()
  return tradMap.get(ch) ?? ch
}

/** 整串繁转简（逐字，够搜索用） */
export function simplify(text) {
  ensure()
  let out = ''
  for (const ch of String(text)) out += tradMap.get(ch) ?? ch
  return out
}
